"use client";

import { useEffect, useRef, useState } from "react";

function useCountUp(end: number, duration: number = 2000, start: boolean = false) {
  const [count, setCount] = useState(0);
  const frameRef = useRef<number>(0);
  const startedRef = useRef(false);

  useEffect(() => {
    if (!start || startedRef.current) return;
    startedRef.current = true;
    const startTime = performance.now();

    const animate = (now: number) => {
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setCount(Math.floor(eased * end));
      if (progress < 1) {
        frameRef.current = requestAnimationFrame(animate);
      }
    };

    frameRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(frameRef.current);
  }, [start, end, duration]);

  return count;
}

function formatNumber(num: number): string {
  return num.toLocaleString("en-US");
}

export default function Stats() {
  const sectionRef = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = sectionRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.3 }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const apps = useCountUp(1150, 2000, visible);
  const screens = useCountUp(615900, 2500, visible);
  const flows = useCountUp(329200, 2200, visible);

  return (
    <section ref={sectionRef} className="bg-[#f5f5f5]">
      <div className="max-w-6xl mx-auto px-6 py-20 md:py-28">
        <p className="text-center text-xs font-medium text-neutral-400 uppercase tracking-widest mb-12">
          A growing library of
        </p>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
          <div className="text-center">
            <div className="text-5xl md:text-6xl font-semibold text-[#141414] tracking-tight">
              {formatNumber(apps)}
            </div>
            <div className="mt-2 text-sm text-neutral-500 font-medium">apps</div>
          </div>
          <div className="text-center">
            <div className="text-5xl md:text-6xl font-semibold text-[#141414] tracking-tight">
              {formatNumber(screens)}
            </div>
            <div className="mt-2 text-sm text-neutral-500 font-medium">screens</div>
          </div>
          <div className="text-center">
            <div className="text-5xl md:text-6xl font-semibold text-[#141414] tracking-tight">
              {formatNumber(flows)}
            </div>
            <div className="mt-2 text-sm text-neutral-500 font-medium">flows</div>
          </div>
        </div>
      </div>
    </section>
  );
}

"use client";

import { RiFigmaLine, RiFolderAddLine, RiChat1Line } from "@remixicon/react";

const tools = [
  {
    icon: RiFigmaLine,
    title: "Copy to Figma",
    description: "Download designs you like or copy them straight into Figma with our new Figma plugin.",
    color: "bg-[#6366f1]/10 text-[#6366f1]",
  },
  {
    icon: RiFolderAddLine,
    title: "Save to collections",
    description: "Collect your favorite designs and upload your own screenshots into one place.",
    color: "bg-emerald-500/10 text-emerald-600",
  },
  {
    icon: RiChat1Line,
    title: "Leave comments",
    description: "Take notes upon saving so you'll never forget the context in the future.",
    color: "bg-amber-500/10 text-amber-600",
  },
];

export default function FeaturesTools() {
  return (
    <section className="bg-white py-20 md:py-28">
      <div className="max-w-6xl mx-auto px-6">
        <div className="text-center mb-14">
          <h2 className="text-3xl md:text-4xl font-semibold text-[#141414] tracking-tight">
            From inspiration to creation.
          </h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {tools.map((tool) => {
            const Icon = tool.icon;
            return (
              <div
                key={tool.title}
                className="group bg-[#f5f5f5] rounded-2xl p-8 transition-all duration-200 hover:shadow-md hover:bg-white border border-transparent hover:border-neutral-100"
              >
                <div className={`w-12 h-12 rounded-xl ${tool.color} flex items-center justify-center mb-5`}>
                  <Icon size={24} />
                </div>
                <h3 className="text-lg font-semibold text-[#141414] mb-2">{tool.title}</h3>
                <p className="text-sm text-neutral-500 leading-relaxed">{tool.description}</p>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
